sys_script.script:
// BR for populating the swift messages in the swift message table when a record is updated in ondemand swift table
// BR also updates attribute sync and Last Refresh date Time in Trade table

(function executeRule(current, previous /*null when async*/ ) {
    try {
        // Add your code here
        var tradeData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
        tradeData.addQuery("sys_id", current.trade_reference);
        tradeData.query();
        if (tradeData.next()) {
            if (current.task_reference != "") {
                var taskRecord = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task");
                taskRecord.get(current.task_reference);
            }
            var swiftMessage = new GlideRecord("x_hsb11_mss_c_swft_mss_custody_swift_messages");
            if (current.response_code == "200") {
                var responsebody = current.response_body.toString().replaceAll("\n", "\\n");
                var respBody = JSON.parse(responsebody);
                for (var i = 0; i < respBody.data.length; i++) {
                    swiftMessage.initialize();
                    swiftMessage.addQuery("message_source_id", respBody.data[i].messageSourceIdentification);
                    swiftMessage.addQuery("trade_id", current.trade_reference);
                    swiftMessage.query();
                    if (swiftMessage.next()) {
                        swiftMessage.message_source_system = respBody.data[i].messageSourceSystemName;
                        swiftMessage.message_source_id = respBody.data[i].messageSourceIdentification;
                        swiftMessage.message_source_timestamp = respBody.data[i].messageSourceTimestamp;
                        swiftMessage.message_channel = respBody.data[i].messageChannelType;
                        swiftMessage.message_format = respBody.data[i].messageFormatType;
                        swiftMessage.message_function_type = respBody.data[i].messageFunctionType;
                        swiftMessage.message_status = respBody.data[i].messageProcessingStatus;
                        swiftMessage.sender_id = respBody.data[i].senderIdentification;
                        swiftMessage.owning_business = respBody.data[i].owningBusinessName;
                        swiftMessage.exception_message_text = respBody.data[i].exceptionMessageText;
                        swiftMessage.message_content = respBody.data[i].messageContentText;
                        swiftMessage.trade_id = current.trade_reference;
                        swiftMessage.trade_base = current.trade_reference; //Custody Redesign
                        swiftMessage.update();
                    } else {
                        swiftMessage.initialize();
                        swiftMessage.message_source_system = respBody.data[i].messageSourceSystemName;
                        swiftMessage.message_source_id = respBody.data[i].messageSourceIdentification;
                        swiftMessage.message_source_timestamp = respBody.data[i].messageSourceTimestamp;
                        swiftMessage.message_channel = respBody.data[i].messageChannelType;
                        swiftMessage.message_format = respBody.data[i].messageFormatType;
                        swiftMessage.message_function_type = respBody.data[i].messageFunctionType;
                        swiftMessage.message_status = respBody.data[i].messageProcessingStatus;
                        swiftMessage.sender_id = respBody.data[i].senderIdentification;
                        swiftMessage.owning_business = respBody.data[i].owningBusinessName;
                        swiftMessage.exception_message_text = respBody.data[i].exceptionMessageText;
                        swiftMessage.message_content = respBody.data[i].messageContentText;
                        swiftMessage.trade_id = current.trade_reference;
                        swiftMessage.trade_base = current.trade_reference; //Custody Redesign
                        swiftMessage.insert();
                    }
                }

                tradeData.swift_attribute_sync = "Response Success-All fields updated(200)";
                tradeData.last_swift_refresh_date_time = new GlideDateTime(); // needs to be checked

                if (current.task_reference != "") {
                    taskRecord.swift_attribute_sync = "Response Success-All fields updated(200)";
                    taskRecord.update();
                }
            } else if (current.response_code.toString().startsWith('4')) { //7426---------START
                gs.info("swift IN 73");
                tradeData.swift_attribute_sync = "Response Un-Successful-400 Client Error";
                tradeData.last_swift_refresh_date_time = new GlideDateTime();
            } else if (current.response_code.toString().startsWith('5')) {
                tradeData.swift_attribute_sync = "Response Un-Successful-500 Server Error";
                tradeData.last_swift_refresh_date_time = new GlideDateTime(); //7426-------END
            } else {
                tradeData.swift_attribute_sync = "Response Un-Successful - Error";
                tradeData.last_swift_refresh_date_time = new GlideDateTime(); // needs to be checked

                if (current.task_reference != "") {
                    taskRecord.swift_attribute_sync = "Response Un-Successful - Error";
                    taskRecord.update();
                }
            }
            // } else {
            //     tradeData.swift_attribute_sync = "Response Un-Successful - Error";
            //     tradeData.last_swift_refresh_date_time = new GlideDateTime(); // needs to be checked

            //     if (current.task_reference != "") {
            //         taskRecord.swift_attribute_sync = "Response Un-Successful - Error";
            //         taskRecord.update();
            //     }
            // }

            tradeData.update();
        }
    } catch (e) {
        gs.info("unexpected error occured" + e);
    }

})(current, previous);
